ST.xhtml:
// =============================================================================
// 场景：EL6022 串口或第三方网关已收到完整 4 字节协议帧（含 CRC 字段在尾部
//       但本例已剥离），需要本端计算 CRC 与帧尾 CRC 比对决定是否接受。
// 价值：相比 F_BYTE_TO_CRC16_CCITT 流式累积，整帧一次调用更简洁，性能
//       由 Beckhoff 优化好；初值 0xFFFF 是 X.25/HDLC 标准。
// 验证步骤：
//   1. 登录后写 arPayloadFrame := [16#01, 16#02, 16#03, 16#04]。
//   2. 写 wExpectedCrc := 16#89C3（这就是 0x01020304 在 0xFFFF 初值下的 CRC）。
//   3. 写 bVerifyRequest := TRUE。
//   4. 观察 wComputedCrc 变为 0x89C3，bFrameValid = TRUE。
//   5. 把 wExpectedCrc 改成 0x0000 重新触发：bFrameValid = FALSE——印证 CRC 校验作用。
//   6. 把 arPayloadFrame[2] 从 16#03 改成 16#13，wComputedCrc 完全不同，
//      bFrameValid = FALSE——印证"1 bit 翻转能被 CRC 检出"。
// =============================================================================

// 准备测试帧
arPayloadFrame[0] := 16#01;
arPayloadFrame[1] := 16#02;
arPayloadFrame[2] := 16#03;
arPayloadFrame[3] := 16#04;
wExpectedCrc := 16#89C3;   // 预期 CRC（对应初值 0xFFFF + 上述 4 字节）

IF bVerifyRequest THEN
    // 单次调用整帧 CRC：crc 初值用 X.25/HDLC 标准 0xFFFF
    wComputedCrc := F_DATA_TO_CRC16_CCITT(
        pData  := ADR(arPayloadFrame),
        cbData := SIZEOF(arPayloadFrame),
        crc    := 16#FFFF);
    bFrameValid := (wComputedCrc = wExpectedCrc);
    bVerifyRequest := FALSE;
END_IF;
